<?php require '../../includes/header.php';require '../../includes/role_guard.php';requireRole(['admin']);require '../../includes/db.php';$id=(int)($_GET['id']??0);$stmt=$conn->prepare('SELECT land_name FROM ip_land_parcels WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$parcel=$stmt->get_result()->fetch_assoc();if(!$parcel){http_response_code(404);exit('Parcel not found.');}$stmt=$conn->prepare('SELECT id,td_number,owner_name,tax_status FROM tax_declarations WHERE parcel_id=? ORDER BY effectivity_year DESC,id DESC');$stmt->bind_param('i',$id);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);?><main class="main-no-right"><div class="page-heading"><div><h4>Related Tax Declarations</h4><p><?=e($parcel['land_name'])?></p></div><a class="btn btn-light border" href="../admin/gis.php?parcel_id=<?=$id?>">Back to map</a></div><div class="card-box"><?php if(!$rows):?><div class="empty-state"><h5>No linked declarations</h5><p>Tax Declarations remain valid without fabricated map data.</p></div><?php endif;?><?php foreach($rows as$r):?><a class="d-flex justify-content-between border-bottom py-3 text-decoration-none" href="view.php?id=<?=$r['id']?>"><span><strong><?=e($r['td_number'])?></strong><small class="d-block text-muted"><?=e($r['owner_name'])?></small></span><span class="badge bg-secondary align-self-center"><?=e($r['tax_status']?:'unclassified')?></span></a><?php endforeach;?></div></main><?php require '../../includes/footer.php';?>
